<script lang="ts">
  import {t,language,formatNumber,formatDate,LocalizedError,errorText} from './i18n';
  import {onMount} from 'svelte';
  import {api,request,setToken,stream,download,cleanConfiguration} from './api';
  import type {Configuration,Conversation,Profile,Provider,ServerEvent,Side} from './api';
  import ConfigForm from './ConfigForm.svelte';
  import ConversationView from './ConversationView.svelte';
  import ConfirmDialog from './ConfirmDialog.svelte';
  import ModelSelector from './ModelSelector.svelte';
  import Toast from './Toast.svelte';
  import LanguageSelector from './LanguageSelector.svelte';
  const buildVersion=__ALTERECHO_VERSION__;
  import {configurationValid,validSelection,profileSignature} from './catalog';
  import {applyEvent} from './conversation';
  let connected=false,token='',notice='',busy=false;
  let error:unknown='';
  $: renderedError=errorText(error,$language);
  let page='dashboard',theme='dark',query='',filter='',providerFilter='';
  let status:any=null,conversations:Conversation[]=[],profiles:Profile[]=[],catalogs:Provider[]=[];
  let config:Configuration,form:Configuration,selected:Conversation|null=null;
  let confirmPaid=false,resumePaid=false,resumeTurns=20;
  let controller:AbortController|undefined;
  let catalogLoading=false,catalogPromise:Promise<void>|null=null;
  let savedProfiles:Profile[]=[];
  let dialog:''|'create'|'delete'|'resume'='',dialogDemo=false,deleteTarget:Conversation|null=null;
  $: validForm=form&&configurationValid(form,catalogs);
  const sides:Side[]=['A','B'];
  $: billable=form&&Object.values(form.participants).some(p=>profiles.find(v=>v.id===p.profile_id)?.billable);
  $: visible=conversations.filter(c=>(c.config.topic+' '+c.id).toLowerCase().includes(query.toLowerCase())&&(!filter||c.status===filter)&&(!providerFilter||Object.values(c.config.participants).some(p=>p.provider===providerFilter)));
  $: totalTokens=conversations.reduce((sum,c)=>sum+Object.values(c.stats.speakers).reduce((s,p)=>s+p.input_tokens+p.output_tokens,0),0);
  $: totalSeconds=conversations.reduce((sum,c)=>sum+c.stats.seconds,0);
  let labels:Record<string,string>;
  $: labels={completed:$t('web.completed'),running:$t('web.running'),starting:$t('web.starting'),interrupted:$t('web.interrupted'),paused:$t('web.paused'),failed:$t('web.error'),stopped:$t('web.stopped'),ready:$t('web.ready')};
  function showError(e:unknown){error=e;}
  async function action(fn:()=>Promise<void>){error='';busy=true;try{await fn();}catch(e){showError(e);}finally{busy=false;}}
  async function refresh(){[status,conversations]=await Promise.all([api('/status'),api('/conversations')]);}
  async function loadProfiles(){profiles=await api('/profiles');savedProfiles=structuredClone(profiles);catalogs=await api('/models');}
  async function login(){await action(async()=>{setToken(token.trim());config=await api('/settings');form=structuredClone(config);await loadProfiles();await refresh();connected=true;token='';const id=new URLSearchParams(location.hash.slice(1)).get('conversation');if(id)await openConversation(id);});}
  function logout(){controller?.abort();setToken('');connected=false;selected=null;conversations=[];profiles=[];error='';}
  async function diagnose(){if(catalogPromise)return catalogPromise;catalogLoading=true;catalogPromise=(async()=>{try{catalogs=(await api('/doctor','POST',{})).providers;notice='web.catalogs_refreshed_without_inference';}catch(e){showError(e);}finally{catalogLoading=false;catalogPromise=null;}})();return catalogPromise;}
  function navigate(next:string){controller?.abort();page=next;error='';notice='';if(next==='new'){form=structuredClone(config);confirmPaid=false;}if(['new','settings'].includes(next)&&!catalogs.length)void diagnose();location.hash='';}
  function create(demo=false){if(dialog)return;if(!demo&&!validForm){error=new LocalizedError('web.verify_catalogs_and_select_valid_models_and_reasoning_levels');return;}dialogDemo=demo;confirmPaid=false;dialog='create';}
  async function startConfirmed(){await action(async()=>{if(!dialogDemo&&(!validForm||billable&&!confirmPaid))throw new LocalizedError('web.invalid_selection_or_cost_confirmation');const result=await api('/conversations','POST',{configuration:cleanConfiguration(form),confirm_paid:confirmPaid,demo:dialogDemo});dialog='';await openConversation(result.id);await refresh();});}
  function onEvent(event:ServerEvent){if(selected?.id===event.conversation_id)selected=applyEvent(selected,event);}
  async function openConversation(id:string){controller?.abort();const state=await api<Conversation>(`/conversations/${id}`);selected=state;resumeTurns=state.messages.length+10;resumePaid=false;page='conversation';location.hash='conversation='+id;controller=new AbortController();const current=controller;stream(id,onEvent,current.signal,()=>notice='web.connection_interrupted_reconnecting').then(()=>{if(!current.signal.aborted)return refresh();}).catch(e=>{if(!current.signal.aborted)showError(e);});}
  async function control(operation:string){if(!selected)return;await action(async()=>{await api(`/conversations/${selected!.id}/${operation}`,'POST',{});if(operation==='pause')selected={...selected!,pause_requested:true};await refresh();});}
  async function resume(){if(!selected)return;await action(async()=>{if(Object.values(selected!.config.participants).some(p=>p.billable)&&!resumePaid)throw new LocalizedError('web.confirm_api_costs');await api(`/conversations/${selected!.id}/preflight`,'POST',{});await api(`/conversations/${selected!.id}/resume`,'POST',{max_turns:resumeTurns,confirm_paid:resumePaid});dialog='';await openConversation(selected!.id);await refresh();});}
  function remove(c:Conversation){if(dialog)return;deleteTarget=c;dialog='delete';}
  async function deleteConfirmed(){if(!deleteTarget)return;await action(async()=>{await request(`/conversations/${deleteTarget!.id}`,'DELETE');dialog='';selected=null;navigate('history');await refresh();});}
  async function saveSettings(){await action(async()=>{if(!validForm)throw new LocalizedError('web.select_available_models_from_verified_catalogs');config=await api('/settings','PUT',cleanConfiguration(form));notice='web.server_settings_saved';});}
  async function saveProfiles(){await action(async()=>{for(const p of profiles){const old=savedProfiles.find(v=>v.id===p.id);if(p.model&&p.model!==old?.model&&!validSelection(p.id,p.model,catalogs))throw new LocalizedError('web.choose_the_preferred_model_from_the_saved_profile_catalog');}profiles=await api('/profiles','PUT',{profiles:profiles.map(({billable,...p})=>p)});savedProfiles=structuredClone(profiles);notice='web.profiles_saved_on_the_server_histories_retain_their_own_configuration';await diagnose();});}
  function addProfile(){profiles=[...profiles,{id:'profile-'+Date.now()+'-'+Math.random().toString(16).slice(2),name:$t('web.new_profile'),provider:'ollama',model:'',url:'http://localhost:11434',api_key_env:''}];}
  function providerChanged(p:Profile){p.model='';p.url=p.provider==='openai'?'https://api.openai.com/v1':p.provider==='openrouter'?'https://openrouter.ai/api/v1':p.provider==='ollama'?'http://localhost:11434':'';p.api_key_env=p.provider==='openai'?'OPENAI_API_KEY':p.provider==='openrouter'?'OPENROUTER_API_KEY':'';profiles=[...profiles];}
  async function copy(text:string){try{await navigator.clipboard.writeText(text);notice='web.text_copied';}catch{error=new LocalizedError('web.automatic_copy_unavailable_select_the_text_or_use_https');}}
  function toggleTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('alterecho-theme',theme);}
  onMount(()=>{theme=localStorage.getItem('alterecho-theme')||'dark';document.documentElement.dataset.theme=theme;const timer=setInterval(()=>{if(connected&&!busy&&page!=='conversation')refresh().catch(showError);},8000);return()=>{clearInterval(timer);controller?.abort();};});
</script>

{#if dialog==='create'}
  <ConfirmDialog title={dialogDemo?$t('web.start_a_demo'):$t('web.start_conversation')} confirmLabel={dialogDemo?$t('web.start_demo'):$t('web.start_conversation')} disabled={busy||(!dialogDemo&&billable&&!confirmPaid)} confirm={startConfirmed} cancel={()=>{if(!busy)dialog='';}}>
    <p>{form.topic}</p><dl class="dialog-summary">{#each sides as side}<dt>{$t('web.participant')}{side}</dt><dd>{profiles.find(p=>p.id===form.participants[side].profile_id)?.name} · {dialogDemo?$t('web.simulated'):form.participants[side].model}</dd>{/each}<dt>{$t('web.mode')}</dt><dd>{form.mode==='free'?$t('web.free_dialogue'):form.mode==='debate'?$t('web.debate'):$t('web.blind_experiment')}</dd><dt>{$t('web.maximum_messages')}</dt><dd>{form.max_turns}</dd></dl>
    {#if !dialogDemo&&billable}<div class="paid-notice"><strong>{$t('web.metered_apis')}</strong><p>{$t('web.selected_providers_may_charge_the_server_account')}</p><label class="check"><input type="checkbox" bind:checked={confirmPaid}/>{$t('web.i_explicitly_confirm_the_costs_of_this_conversation')}</label></div>{/if}
    {#if dialogDemo}<p>{$t('web.simulated_providers_no_ai_quota_used')}</p>{/if}
    {#if error}<p role="alert" class="error-text">{renderedError}</p>{/if}
  </ConfirmDialog>
{:else if dialog==='delete'&&deleteTarget}
  <ConfirmDialog title="{$t('web.delete_conversation')}" confirmLabel="{$t('web.delete_permanently')}" danger disabled={busy} confirm={deleteConfirmed} cancel={()=>{if(!busy)dialog='';}}><p>{$t('web.delete_topic',{topic:deleteTarget.config.topic})}</p><p>{$t('web.the_history_backups_and_exports_on_the_server_will_be_removed_this_action_cannot_be_undone')}</p>{#if error}<p role="alert" class="error-text">{renderedError}</p>{/if}</ConfirmDialog>
{:else if dialog==='resume'&&selected}
  <ConfirmDialog title="{$t('web.resume_dialogue')}" confirmLabel="{$t('web.verify_and_resume')}" disabled={busy||resumeTurns<=selected.messages.length||(Object.values(selected.config.participants).some(p=>p.billable)&&!resumePaid)} confirm={resume} cancel={()=>{if(!busy)dialog='';}}>
    <p>{selected.config.topic}</p><p>{Object.values(selected.config.participants).map(p=>p.name+' · '+p.model).join(' ↔ ')}</p><label>{$t('web.new_total_maximum')}<input type="number" min={selected.messages.length+1} max="10000" bind:value={resumeTurns}/></label><p>{$t('web.additional_messages',{saved:$formatNumber(selected.messages.length)},Math.max(0,resumeTurns-selected.messages.length))}</p>
    {#if Object.values(selected.config.participants).some(p=>p.billable)}<label class="check"><input type="checkbox" bind:checked={resumePaid}/>{$t('web.i_confirm_api_costs_for_this_resume')}</label>{/if}{#if error}<p role="alert" class="error-text">{renderedError}</p>{/if}
  </ConfirmDialog>
{/if}

<svelte:head><title>AlterEcho · {page==='conversation'?selected?.config.topic:$t('web.conversations_between_models')}</title></svelte:head>
{#if !connected}
  <main class="login"><div class="brand-mark">a<span>e</span></div><p class="eyebrow">ALTERECHO / {buildVersion}</p><h1>{$t('web.two_perspectives')}<br/>{$t('web.one_conversation')}</h1><p class="muted">{$t('web.connect_to_your_server_to_create_follow_and_resume_conversations_between_models')}</p><form on:submit|preventDefault={login}><label>{$t('web.service_token')}<input type="password" autocomplete="off" required bind:value={token} placeholder="{$t('web.enter_your_alterecho_token')}"/></label><button class="primary" disabled={busy}>{$t('web.connect_to_server')}<span>→</span></button></form><p class="footnote">{$t('web.token_help',{file:'server-token',variable:'ALTERECHO_TOKEN'})}</p>{#if error}<div role="alert" class="alert error">{renderedError}</div>{/if}<button class="text-button" on:click={toggleTheme}>{$t('web.theme',{theme:theme==='dark'?$t('web.light'):$t('web.dark')})}</button><LanguageSelector/></main>
{:else}
  <div class="shell" class:chat-shell={page==='conversation'}><aside><a href="/" class="brand" on:click|preventDefault={()=>navigate('dashboard')}><span class="brand-symbol">a<span>e</span></span><strong>AlterEcho<small>{$t('web.conversations_between_models_label')}</small></strong></a><div class="client-language"><LanguageSelector/></div><nav aria-label="{$t('web.main_navigation')}">{#each [['dashboard',$t('web.dashboard'),'◫'],['new',$t('web.new_conversation'),'＋'],['history',$t('web.history'),'◷'],['settings',$t('web.settings'),'⚙']] as item}<button class:current={page===item[0]} on:click={()=>{navigate(item[0]);if(item[0]==='settings')form=structuredClone(config);}}><span>{item[2]}</span>{item[1]}</button>{/each}</nav><div class="sidebar-bottom"><span class="connection-dot"></span>{$t('web.server_connected')}<small>{status?.version} · {location.host}</small><div class="sidebar-actions"><button on:click={toggleTheme}>{theme==='dark'?$t('web.light_label'):$t('web.dark_label')}</button><button on:click={logout}>{$t('web.disconnect')}</button></div></div></aside>
  <main class="workspace" class:chat-workspace={page==='conversation'}>{#if page!=='conversation'}<header><div><p class="eyebrow">{$t('web.your_space_for_dialogue')}</p><h1>{page==='dashboard'?$t('web.dashboard'):page==='new'?$t('web.new_conversation'):page==='history'?$t('web.history'):page==='settings'?$t('web.settings'):$t('web.conversation')}</h1></div><div class="header-actions"><span class="status-pill"><span class="connection-dot"></span>{$t('web.server_active')}</span>{#if page!=='new'}<button class="primary" on:click={()=>navigate('new')}>{$t('web.new_dialogue')}</button>{/if}</div></header>{/if}
  {#if error}<div class="alert error" role="alert">{error}<button aria-label="{$t('web.dismiss_error')}" on:click={()=>error=''}>×</button></div>{/if}{#if notice}<Toast message={$t(notice)} dismiss={()=>notice=''}/>{/if}

  {#if page==='dashboard'}
    <section class="welcome"><div><p class="eyebrow">{$t('web.perspectives_meet')}</p><h2>{$t('web.make_room_for_ideas')}</h2><p>{$t('web.pair_two_models_choose_a_topic')}<br/>{$t('web.and_follow_the_dialogue_as_it_takes_shape')}</p><button class="primary" on:click={()=>navigate('new')}>{$t('web.create_a_conversation')}<span>↗</span></button></div><div class="orbits" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><span class="orb a">A</span><span class="orb b">B</span><span class="orbit-center">↔</span></div></section>
    <section class="metrics" aria-label="{$t('web.statistics')}"><article><span>{$t('web.active_conversations')}</span><strong>{conversations.filter(c=>c.active).length.toString().padStart(2,'0')}</strong><small>{$t('web.continue_without_clients')}</small></article><article><span>{$t('web.saved_dialogues')}</span><strong>{conversations.length.toString().padStart(2,'0')}</strong><small>{$t('web.one_shared_history')}</small></article><article><span>{$t('web.measured_tokens')}</span><strong>{$formatNumber(totalTokens)}</strong><small>{$t('web.available_input_and_output')}</small></article><article><span>{$t('web.generation_time')}</span><strong>{$formatNumber(totalSeconds,{minimumFractionDigits:1,maximumFractionDigits:1})}<em> s</em></strong><small>{$t('web.sum_of_completed_turns')}</small></article></section>
    <div class="section-heading"><h2>{$t('web.providers_and_models')}</h2><button disabled={busy} on:click={diagnose}>{$t('web.verify_catalogs')}</button></div><section class="provider-grid">{#each profiles as p}<article class="provider-card"><div class="provider-icon">{p.provider==='codex'?'⌘':p.provider==='ollama'?'◉':'↗'}</div><div><h3>{p.name}</h3><p>{p.provider}{p.billable?$t('web.metered_api'):''}</p><small>{catalogs.find(c=>c.profile_id===p.id)?.available?$t('web.models_available',{},catalogs.find(c=>c.profile_id===p.id)?.models.length||0):catalogs.find(c=>c.profile_id===p.id)?.error||$t('web.not_checked')}</small></div><span class:ok={catalogs.find(c=>c.profile_id===p.id)?.available} class="provider-dot"></span></article>{/each}</section>
    <div class="section-heading"><h2>{$t('web.recent_conversations')}</h2><button class="text-button" on:click={()=>navigate('history')}>{$t('web.full_history')}</button></div>
  {/if}

  {#if page==='dashboard'||page==='history'}
    {#if page==='history'}<div class="filters"><input aria-label="{$t('web.search_history')}" placeholder="{$t('web.search_topic_or_id')}" bind:value={query}/><select aria-label="{$t('web.filter_status')}" bind:value={filter}><option value="">{$t('web.all_statuses')}</option>{#each Object.entries(labels) as [key,label]}<option value={key}>{label}</option>{/each}</select><select aria-label="{$t('web.filter_provider')}" bind:value={providerFilter}><option value="">{$t('web.all_providers')}</option><option>codex</option><option>ollama</option><option>openai</option><option>openrouter</option></select></div>{/if}
    <section class="history-list">{#each (page==='dashboard'?conversations.slice(0,5):visible) as c}<article class="history-row"><button class="history-main" on:click={()=>action(()=>openConversation(c.id))}><span class="conversation-icon">↔</span><div><h3>{c.config.topic}</h3><p>{Object.values(c.config.participants).map(p=>p.name||p.provider).join(' ↔ ')} <span>·</span> {$t('web.messages',{},c.message_count??c.messages?.length??0)} <span>·</span> {$formatDate(c.created_at)}</p></div></button><span class="badge" class:running={c.active}>{labels[c.status]||c.status}</span><button class="row-arrow" aria-label="{$t('web.open_conversation')}" on:click={()=>action(()=>openConversation(c.id))}>↗</button></article>{:else}<div class="empty"><span>↔</span><h3>{$t('web.the_next_dialogue_starts_here')}</h3><p>{$t('web.conversations_from_all_clients_will_appear_here')}</p><button on:click={()=>navigate('new')}>{$t('web.create_your_first_dialogue')}</button></div>{/each}</section>
    {#if status?.unreadable_histories}<p class="error-text">{$t('web.unreadable_histories',{},status.unreadable_histories)}</p>{/if}
  {/if}

  {#if page==='new'&&form}<section class="card"><div class="section-heading"><div><h2>{$t('web.set_up_the_dialogue')}</h2><p class="muted">{$t('web.two_participants_one_shared_memory')}</p></div><button on:click={diagnose} disabled={busy}>{$t('web.refresh_models')}</button></div><form on:submit|preventDefault={()=>create()}><ConfigForm bind:value={form} {profiles} {catalogs} loading={catalogLoading} refresh={diagnose}/><div class="form-footer"><small>{$t('web.the_dialogue_continues_if_you_close_this_page')}</small><button type="button" disabled={busy} on:click={()=>create(true)}>{$t('web.try_demo')}</button><button class="primary" disabled={busy||catalogLoading||!validForm}>{$t('web.start_conversation_label')}</button></div></form></section>{/if}

  {#if page==='conversation'&&selected}{#key selected.id}<ConversationView conversation={selected} {busy} {copy} {control} resume={()=>{resumePaid=false;dialog='resume';}} remove={()=>remove(selected!)} download={(fmt)=>action(async()=>{await download(selected!.id,fmt);})}/>{/key}{/if}

  {#if page==='settings'&&form}<section class="card"><LanguageSelector/><p class="muted">{$t('language.local_only')}</p></section><section class="card"><h2>{$t('web.shared_preferences')}</h2><p class="muted">{$t('web.changes_apply_to_future_conversations_from_cli_and_browser')}</p><form on:submit|preventDefault={saveSettings}><ConfigForm bind:value={form} {profiles} {catalogs} loading={catalogLoading} refresh={diagnose} compact/><div class="form-footer"><button class="primary" disabled={busy||catalogLoading||!validForm}>{$t('web.save_to_server')}</button></div></form></section><section class="card"><div class="section-heading"><div><h2>{$t('web.provider_profiles')}</h2><p class="muted">{$t('web.enter_only_the_environment_variable_name_configure_keys_on_the_server')}</p></div><button on:click={addProfile}>{$t('web.profile')}</button></div>{#each profiles as p}<fieldset class="profile-editor"><legend>{p.name}</legend><div class="form-grid"><label>{$t('web.name')}<input bind:value={p.name}/></label><label>{$t('web.provider')}<select bind:value={p.provider} on:change={()=>providerChanged(p)}><option>codex</option><option>ollama</option><option>openai</option><option>openrouter</option></select></label><ModelSelector label="{$t('web.preferred_model')}" bind:value={p.model} profileId={p.id} {catalogs} loading={catalogLoading} refresh={diagnose} optional enabled={savedProfiles.some(v=>profileSignature(v)===profileSignature(p))}/>{#if p.provider==='ollama'}<label>{$t('web.server_authorized_endpoint')}<input bind:value={p.url}/></label>{:else if p.provider==='openai'||p.provider==='openrouter'}<label>{$t('web.key_variable_name')}<input bind:value={p.api_key_env}/></label>{/if}</div><button class="text-button danger" on:click={()=>profiles=profiles.filter(v=>v.id!==p.id)}>{$t('web.remove_profile')}</button></fieldset>{/each}<button class="primary" disabled={busy} on:click={saveProfiles}>{$t('web.save_profiles')}</button></section>{/if}
  {#if page!=='conversation'}<footer class="workspace-footer">AlterEcho <span>{$t('web.one_server_all_your_perspectives')}</span><small>{$t('web.generation_runs_on_the_configured_server')}</small></footer>{/if}
  </main></div>
{/if}
